import { double, greet } from '../lib/utils';

// Mood
export enum Mood {
	HAPPY,
	SAD,
}

export let count: number = 0;

function classify(n: number): string {
	if (n === 1) {
		return 'one';
	} else if (n === 2) {
		return 'two';
	} else {
		return 'many';
	}
}

